<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <div id="app"></div>

  <script>
    const formState = {
      touched: new Set(),
      values: {
        fullName: "",
        email: "",
        phone: ""
      }
    };

    const fieldConfig = [
      {
        id: "fullName",
        label: "Full name",
        type: "text",
        autocomplete: "name",
        required: true,
        placeholder: "Ada Lovelace"
      },
      {
        id: "email",
        label: "Email address",
        type: "email",
        autocomplete: "email",
        required: true,
        placeholder: "ada@example.com"
      },
      {
        id: "phone",
        label: "Phone number",
        type: "tel",
        autocomplete: "tel",
        required: false,
        placeholder: "+1 (555) 123-4567",
        helpText: "Optional. Use digits, spaces, parentheses, dashes, or +; for example: +1 (555) 123-4567."
      }
    ];

    function escapeHtml(value) {
      return value
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#39;");
    }

    function fieldTemplate(field) {
      const helpId = `${field.id}-help`;
      const errorId = `${field.id}-error`;
      const describedBy = [field.helpText ? helpId : "", errorId].filter(Boolean).join(" ");
      const requiredMark = field.required ? ' <span class="required" aria-hidden="true">*</span>' : "";
      const helpText = field.helpText ? `<p class="field-help" id="${helpId}">${escapeHtml(field.helpText)}</p>` : "";

      return `
        <div class="form-field">
          <label for="${field.id}">${field.label}${requiredMark}</label>
          <input
            id="${field.id}"
            name="${field.id}"
            type="${field.type}"
            autocomplete="${field.autocomplete}"
            ${field.required ? "required" : ""}
            aria-describedby="${describedBy}"
            aria-invalid="false"
            placeholder="${escapeHtml(field.placeholder)}"
          />
          ${helpText}
          <p class="field-error" id="${errorId}" aria-live="polite"></p>
        </div>
      `;
    }

    function appTemplate() {
      return `
        <main id="main-content" class="page">
          <section class="hero" aria-labelledby="support-title">
            <div class="hero-copy">
              <span class="eyebrow">Support</span>
              <h1 id="support-title">Contact our support team</h1>
              <p>Send us your details and we will route your request to the right specialist. Required fields are marked with an asterisk.</p>
            </div>

            <div class="form-shell">
              <form class="form-card" id="support-form" novalidate>
                <div class="form-header">
                  <h2>Request details</h2>
                  <p>Use the form below to get in touch with support.</p>
                </div>

                ${fieldConfig.map(fieldTemplate).join("")}

                <div class="actions">
                  <button type="submit">Submit request</button>
                  <p class="form-note">We will never share your contact details.</p>
                </div>
                <p class="status" id="form-status" aria-live="polite"></p>
              </form>
            </div>
          </section>
        </main>
      `;
    }

    function validateEmail(value) {
      return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim());
    }

    function validatePhone(value) {
      if (!value.trim()) return true;
      const digits = value.replace(/\D/g, "");
      const allowed = /^[0-9()+\-\s.]+$/.test(value);
      return allowed && digits.length >= 7 && digits.length <= 15;
    }

    function getFieldMessage(fieldId, value) {
      const trimmed = value.trim();

      if (fieldId === "fullName" && !trimmed) {
        return "Full name is required.";
      }

      if (fieldId === "email") {
        if (!trimmed) return "Email address is required.";
        if (!validateEmail(trimmed)) return "Enter a valid email address.";
      }

      if (fieldId === "phone" && !validatePhone(value)) {
        return "Enter a valid phone number, or leave it blank.";
      }

      return "";
    }

    function setFieldError(fieldId, message) {
      const input = document.getElementById(fieldId);
      const error = document.getElementById(`${fieldId}-error`);
      input.setAttribute("aria-invalid", message ? "true" : "false");
      error.textContent = message;
    }

    function validateField(fieldId) {
      const input = document.getElementById(fieldId);
      const message = getFieldMessage(fieldId, input.value);
      setFieldError(fieldId, message);
      return !message;
    }

    function validateAll() {
      return fieldConfig.map((field) => validateField(field.id)).every(Boolean);
    }

    function renderApp() {
      document.getElementById("app").innerHTML = appTemplate();

      const form = document.getElementById("support-form");
      const status = document.getElementById("form-status");

      fieldConfig.forEach((field) => {
        const input = document.getElementById(field.id);
        input.addEventListener("input", (event) => {
          formState.values[field.id] = event.target.value;
          if (formState.touched.has(field.id)) {
            validateField(field.id);
          }
        });
        input.addEventListener("blur", () => {
          formState.touched.add(field.id);
          validateField(field.id);
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        fieldConfig.forEach((field) => formState.touched.add(field.id));

        const isValid = validateAll();

        if (!isValid) {
          const firstInvalid = fieldConfig.find((field) => document.getElementById(field.id).getAttribute("aria-invalid") === "true");
          if (firstInvalid) {
            document.getElementById(firstInvalid.id).focus();
          }
          status.textContent = "";
          return;
        }

        status.textContent = "Your details are ready to send.";
      });
    }

    renderApp();
  </script>
