      z-index: 10;
      border-radius: 0 0 10px 0;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    .page {
      width: min(100%, 1120px);
      margin: 0 auto;
      padding: 1.25rem;
    }

    .hero {
      display: grid;
      gap: 1.5rem;
      grid-template-columns: 1.1fr 0.9fr;
      align-items: stretch;
      min-width: 0;
      padding: 1rem 0 2rem;
    }

    .hero-copy,
    .form-shell {
      min-width: 0;
    }

    .hero-copy {
      display: grid;
      align-content: center;
      gap: 0.9rem;
      padding: clamp(1.25rem, 3vw, 3rem) 0;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      width: fit-content;
      padding: 0.35rem 0.8rem;
      border: 1px solid #bfdbfe;
      border-radius: 999px;
      background: #eff6ff;
      color: #1d4ed8;
      font-weight: 600;
      letter-spacing: 0.01em;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 4vw, 3.75rem);
      line-height: 1.05;
      letter-spacing: -0.04em;
    }

    .hero-copy p {
      margin: 0;
      max-width: 58ch;
      color: var(--muted);
      font-size: 1.05rem;
    }

    .form-shell {
      border: 1px solid rgba(148, 163, 184, 0.35);
      border-radius: var(--radius-lg);
      background: rgba(255, 255, 255, 0.88);
      box-shadow: var(--shadow);
      backdrop-filter: blur(14px);
      padding: var(--space);
    }

    .form-card {
      display: grid;
      gap: 1rem;
    }

    .form-header {
      display: grid;
      gap: 0.35rem;
      margin-bottom: 0.5rem;
    }

    .form-header h2 {
      margin: 0;
      font-size: 1.35rem;
    }

    .form-header p {
      margin: 0;
      color: var(--muted);
    }

    .form-field {
      display: grid;
      gap: 0.45rem;
    }

    .form-field label {
      font-weight: 600;
      color: var(--text);
    }

    .required {
      color: var(--error);
    }

    input {
      width: 100%;
      min-width: 0;
      padding: 0.95rem 1rem;
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      background: var(--surface);
      color: var(--text);
      font: inherit;
      transition: border-color 120ms ease, box-shadow 120ms ease, background-color 120ms ease;
    }

    input::placeholder {
      color: #94a3b8;
    }

    input:hover {
      border-color: var(--border-strong);
    }

    input:focus-visible,
    button:focus-visible,
    .skip-link:focus {
      outline: 3px solid var(--focus);
      outline-offset: 2px;
    }

    input[aria-invalid="true"] {
      border-color: var(--error);
      background: var(--error-bg);
    }

    .field-help,
    .field-error {
      margin: 0;
      font-size: 0.92rem;
      line-height: 1.4;
    }

    .field-help {
      color: var(--muted);
    }

    .field-error {
      color: var(--error);
      min-height: 1.35em;
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
      align-items: center;
      margin-top: 0.25rem;
    }

    button {
      border: 0;
      border-radius: 999px;
      padding: 0.95rem 1.35rem;
      background: linear-gradient(135deg, var(--accent), var(--accent-dark));
      color: #fff;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      box-shadow: 0 12px 30px rgba(37, 99, 235, 0.24);
    }

    button:hover {
      filter: brightness(1.02);
    }

    .form-note {
      color: var(--muted);
      font-size: 0.92rem;
      margin: 0;
    }

    .status {
      margin: 0;
      min-height: 1.4em;
      color: var(--accent-dark);
      font-weight: 600;
    }

    @media (max-width: 860px) {
      .hero {
        grid-template-columns: 1fr;
      }
    }

    @media (max-width: 560px) {
      .page {
        padding: 0.8rem;
      }

      .form-shell {
        padding: 1rem;
      }

      button {
        width: 100%;
        justify-content: center;
      }
    }

    @media (forced-colors: active) {
      :root {
        --bg: Canvas;
        --surface: Canvas;
        --surface-2: Canvas;
        --text: CanvasText;
        --muted: CanvasText;
        --border: ButtonBorder;
        --border-strong: ButtonBorder;
        --accent: ButtonText;
        --accent-dark: ButtonText;
        --error: CanvasText;
        --error-bg: Canvas;
        --focus: Highlight;
      }

      .form-shell,
      input,
      button,
      .eyebrow,
      .skip-link {
        forced-color-adjust: auto;
      }

      button {
        border: 1px solid ButtonText;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <div id="app"></div>

  <script>
    const formState = {
      touched: new Set(),
      values: {
        fullName: "",
        email: "",
        phone: ""
      }
    };

    const fieldConfig = [
      {
        id: "fullName",
        label: "Full name",
        type: "text",
        autocomplete: "name",
        required: true,
        placeholder: "Ada Lovelace"
      },
      {
        id: "email",
        label: "Email address",
        type: "email",
        autocomplete: "email",
        required: true,
        placeholder: "ada@example.com"
      },
      {
        id: "phone",
        label: "Phone number",
        type: "tel",
        autocomplete: "tel",
        required: false,
        placeholder: "+1 (555) 123-4567",
        helpText: "Optional. Use digits, spaces, parentheses, dashes, or +; for example: +1 (555) 123-4567."
      }
    ];

    function escapeHtml(value) {
      return value
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#39;");
    }

    function fieldTemplate(field) {
      const helpId = `${field.id}-help`;
      const errorId = `${field.id}-error`;
      const describedBy = [field.helpText ? helpId : "", errorId].filter(Boolean).join(" ");
      const requiredMark = field.required ? ' <span class="required" aria-hidden="true">*</span>' : "";
      const helpText = field.helpText ? `<p class="field-help" id="${helpId}">${escapeHtml(field.helpText)}</p>` : "";

      return `
        <div class="form-field">
          <label for="${field.id}">${field.label}${requiredMark}</label>
          <input
            id="${field.id}"
            name="${field.id}"
            type="${field.type}"
            autocomplete="${field.autocomplete}"
            ${field.required ? "required" : ""}
            aria-describedby="${describedBy}"
            aria-invalid="false"
            placeholder="${escapeHtml(field.placeholder)}"
          />
          ${helpText}
          <p class="field-error" id="${errorId}" aria-live="polite"></p>
        </div>
      `;
    }

    function appTemplate() {
      return `
        <main id="main-content" class="page">
          <section class="hero" aria-labelledby="support-title">
            <div class="hero-copy">
              <span class="eyebrow">Support</span>
              <h1 id="support-title">Contact our support team</h1>
              <p>Send us your details and we will route your request to the right specialist. Required fields are marked with an asterisk.</p>
            </div>

            <div class="form-shell">
              <form class="form-card" id="support-form" novalidate>
                <div class="form-header">
                  <h2>Request details</h2>
                  <p>Use the form below to get in touch with support.</p>
                </div>

                ${fieldConfig.map(fieldTemplate).join("")}

                <div class="actions">
                  <button type="submit">Submit request</button>
                  <p class="form-note">We will never share your contact details.</p>
                </div>
                <p class="status" id="form-status" aria-live="polite"></p>
              </form>
            </div>
          </section>
        </main>
      `;
    }

    function validateEmail(value) {
      return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim());
    }

    function validatePhone(value) {
      if (!value.trim()) return true;
      const digits = value.replace(/\D/g, "");
      const allowed = /^[0-9()+\-\s.]+$/.test(value);
      return allowed && digits.length >= 7 && digits.length <= 15;
    }

    function getFieldMessage(fieldId, value) {
      const trimmed = value.trim();

      if (fieldId === "fullName" && !trimmed) {
        return "Full name is required.";
      }

      if (fieldId === "email") {
        if (!trimmed) return "Email address is required.";
        if (!validateEmail(trimmed)) return "Enter a valid email address.";
      }

      if (fieldId === "phone" && !validatePhone(value)) {
        return "Enter a valid phone number, or leave it blank.";
      }

      return "";
    }

    function setFieldError(fieldId, message) {
      const input = document.getElementById(fieldId);
      const error = document.getElementById(`${fieldId}-error`);
      input.setAttribute("aria-invalid", message ? "true" : "false");
      error.textContent = message;
    }

    function validateField(fieldId) {
      const input = document.getElementById(fieldId);
      const message = getFieldMessage(fieldId, input.value);
      setFieldError(fieldId, message);
      return !message;
    }

    function validateAll() {
      return fieldConfig.map((field) => validateField(field.id)).every(Boolean);
    }

    function renderApp() {
      document.getElementById("app").innerHTML = appTemplate();

      const form = document.getElementById("support-form");
      const status = document.getElementById("form-status");

      fieldConfig.forEach((field) => {
        const input = document.getElementById(field.id);
        input.addEventListener("input", (event) => {
          formState.values[field.id] = event.target.value;
          if (formState.touched.has(field.id)) {
            validateField(field.id);
          }
        });
        input.addEventListener("blur", () => {
          formState.touched.add(field.id);
          validateField(field.id);
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        fieldConfig.forEach((field) => formState.touched.add(field.id));

        const isValid = validateAll();

        if (!isValid) {
          const firstInvalid = fieldConfig.find((field) => document.getElementById(field.id).getAttribute("aria-invalid") === "true");
          if (firstInvalid) {
            document.getElementById(firstInvalid.id).focus();
          }
          status.textContent = "";
          return;
        }

        status.textContent = "Your details are ready to send.";
      });
    }

    renderApp();
  </script>
</body>
</html>
