 <!doctype html>
 <html lang="en">
 <head>
   <meta charset="utf-8" />
   <meta name="viewport" content="width=device-width, initial-scale=1" />
   <title>Support Contact Form</title>
   <style>
     :root {
       color-scheme: light;
       --bg: #f4f7fb;
       --surface: #ffffff;
       --surface-2: #f8fafc;
       --text: #0f172a;
       --muted: #475569;
       --border: #cbd5e1;
       --border-strong: #94a3b8;
       --accent: #2563eb;
       --accent-dark: #1d4ed8;
       --error: #b42318;
       --error-bg: #fef3f2;
       --shadow: 0 20px 60px rgba(15, 23, 42, 0.12);
       --radius-lg: 24px;
       --radius-md: 14px;
       --radius-sm: 10px;
       --space: clamp(1rem, 2vw, 1.5rem);
       --focus: #0f62fe;
     }

     * {
       box-sizing: border-box;
     }

     html {
       scroll-behavior: smooth;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font: 16px/1.5 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       color: var(--text);
       background:
         radial-gradient(circle at top, #e0ecff 0%, transparent 42%),
         linear-gradient(180deg, #eef4ff 0%, var(--bg) 42%, #edf2f7 100%);
     }

     a {
       color: var(--accent);
     }

     a:hover {
       color: var(--accent-dark);
     }

     .skip-link {
       position: absolute;
       top: 0;
       left: 0;
       transform: translateY(-120%);
       background: var(--text);
       color: #fff;
       padding: 0.75rem 1rem;
       z-index: 10;
       border-radius: 0 0 10px 0;
     }

     .skip-link:focus {
       transform: translateY(0);
     }

     .page {
       width: min(100%, 1120px);
       margin: 0 auto;
       padding: 1.25rem;
     }

     .hero {
       display: grid;
       gap: 1.5rem;
       grid-template-columns: 1.1fr 0.9fr;
       align-items: stretch;
       min-width: 0;
       padding: 1rem 0 2rem;
     }

     .hero-copy,
     .form-shell {
       min-width: 0;
     }

     .hero-copy {
       display: grid;
       align-content: center;
       gap: 0.9rem;
       padding: clamp(1.25rem, 3vw, 3rem) 0;
     }

     .eyebrow {
       display: inline-flex;
       align-items: center;
       gap: 0.5rem;
       width: fit-content;
       padding: 0.35rem 0.8rem;
       border: 1px solid #bfdbfe;
       border-radius: 999px;
       background: #eff6ff;
       color: #1d4ed8;
       font-weight: 600;
       letter-spacing: 0.01em;
     }

     h1 {
       margin: 0;
       font-size: clamp(2rem, 4vw, 3.75rem);
       line-height: 1.05;
       letter-spacing: -0.04em;
     }

     .hero-copy p {
       margin: 0;
       max-width: 58ch;
       color: var(--muted);
       font-size: 1.05rem;
     }

     .form-shell {
       border: 1px solid rgba(148, 163, 184, 0.35);
       border-radius: var(--radius-lg);
       background: rgba(255, 255, 255, 0.88);
       box-shadow: var(--shadow);
       backdrop-filter: blur(14px);
       padding: var(--space);
     }

     .form-card {
       display: grid;
       gap: 1rem;
     }

     .form-header {
       display: grid;
       gap: 0.35rem;
       margin-bottom: 0.5rem;
     }

     .form-header h2 {
       margin: 0;
       font-size: 1.35rem;
     }

     .form-header p {
       margin: 0;
       color: var(--muted);
     }

     .form-field {
       display: grid;
       gap: 0.45rem;
     }

     .form-field label {
       font-weight: 600;
       color: var(--text);
     }

     .required {
       color: var(--error);
     }

     input {
       width: 100%;
       min-width: 0;
       padding: 0.95rem 1rem;
       border: 1px solid var(--border);
       border-radius: var(--radius-md);
       background: var(--surface);
       color: var(--text);
       font: inherit;
       transition: border-color 120ms ease, box-shadow 120ms ease, background-color 120ms ease;
     }

     input::placeholder {
       color: #94a3b8;
     }

     input:hover {
       border-color: var(--border-strong);
     }

     input:focus-visible,
     button:focus-visible,
     .skip-link:focus {
       outline: 3px solid var(--focus);
       outline-offset: 2px;
     }

     input[aria-invalid="true"] {
       border-color: var(--error);
       background: var(--error-bg);
     }

     .field-help,
     .field-error {
       margin: 0;
       font-size: 0.92rem;
       line-height: 1.4;
     }

     .field-help {
       color: var(--muted);
     }

     .field-error {
       color: var(--error);
       min-height: 1.35em;
     }

     .actions {
       display: flex;
       flex-wrap: wrap;
       gap: 0.75rem;
       align-items: center;
       margin-top: 0.25rem;
     }

     button {
       border: 0;
       border-radius: 999px;
       padding: 0.95rem 1.35rem;
       background: linear-gradient(135deg, var(--accent), var(--accent-dark));
       color: #fff;
       font: inherit;
       font-weight: 700;
       cursor: pointer;
       box-shadow: 0 12px 30px rgba(37, 99, 235, 0.24);
     }

     button:hover {
       filter: brightness(1.02);
     }

     .form-note {
       color: var(--muted);
       font-size: 0.92rem;
       margin: 0;
     }

     .status {
       margin: 0;
       min-height: 1.4em;
       color: var(--accent-dark);
       font-weight: 600;
     }

     @media (max-width: 860px) {
       .hero {
         grid-template-columns: 1fr;
       }
     }

